mapper.sql:
h.is_deleted = false
and (h.name like concat('%', #{keyword}, '%') or h.remark like concat('%', #{keyword}, '%') or cast(h.id as char) = #{keyword} or exists ( select 1 from house_users keyword_owner join sys_user keyword_owner_user on keyword_owner_user.user_id = keyword_owner.user_id and keyword_owner_user.status = 'ENABLED' where keyword_owner.house_id = h.id and keyword_owner.role = 'OWNER' and keyword_owner.status = 'ENABLED' and keyword_owner_user.user_name like concat('%', #{keyword}, '%') ))
and h.status = #{status}

mapper.select:
select count(1)
from house_users
where house_id = #{houseId}
  and user_id = #{userId}
  and role = 'OWNER'

select count(1)
from house_users hu
join sys_user u on u.user_id = hu.user_id
where hu.house_id = #{houseId}
  and hu.role = 'OWNER'
  and u.phone_hash = #{phoneHash}

select id, trace_id, user_id, house_id, method, path, query_string, status,
       api_code, api_message, cost_ms, error_message, ip, user_agent, create_time
from audit_logs
where house_id = #{houseId}
order by create_time desc, id desc
limit #{limit}
